using System.Net;
using System.Reflection;
using AwesomeAssertions;
using Gaffer.Api.Tests.TestShared;
using Newtonsoft.Json.Linq;

namespace Gaffer.Api.Tests.Acceptance;

/// <summary>
/// The "AutogeneratedClient" document is the source NSwag uses to generate Gaffer.Api.Client,
/// so its info block must carry the product name and the client package version.
/// </summary>
public class ClientOpenApiDocumentShould {
    private StartupTestServer server;
    private JObject info;

    [OneTimeSetUp]
    public async Task OneTimeSetUp() {
        server = await StartupTestServer.StartAsync(TestDefaultValues.TestConnectionString);
        var response = await server.Client.GetAsync("/swagger/AutogeneratedClient/swagger.json");
        var raw = await response.Content.ReadAsStringAsync();
        response.StatusCode.Should().Be(HttpStatusCode.OK, raw);
        info = (JObject)JObject.Parse(raw)["info"]!;
    }

    [OneTimeTearDown]
    public async Task OneTimeTearDown() => await server.DisposeAsync();

    [Test]
    public void UseTheProductNameAsTitle() => info["title"]!.ToString().Should().Be(Program.ProductContext.Name);

    [Test]
    public void UseTheClientPackageVersionAsVersion() {
        var clientVersion = typeof(Startup).Assembly
            .GetCustomAttributes<AssemblyMetadataAttribute>()
            .SingleOrDefault(attribute => attribute.Key == "GafferClientVersion")?.Value;

        clientVersion.Should().NotBeNullOrEmpty();
        info["version"]!.ToString().Should().Be(clientVersion);
    }
}
